import{_ as t,a as i,b as o,c as s,d as a}from"./chunks/vscode-clone-first-time.C0ATSzUj.js";import{_ as n,c as l,o as r,ah as d}from"./chunks/framework.D6otvB2a.js";const b=JSON.parse('{"title":"Setup the Course Dev Container","description":"","frontmatter":{},"headers":[],"relativePath":"dev-container-setup.md","filePath":"dev-container-setup.md","lastUpdated":1787777772000}'),c={name:"dev-container-setup.md"};function h(p,e,u,g,k,m){return r(),l("div",null,e[0]||(e[0]=[d('<h1 id="setup-the-course-dev-container" tabindex="-1">Setup the Course Dev Container <a class="header-anchor" href="#setup-the-course-dev-container" aria-label="Permalink to &quot;Setup the Course Dev Container&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This page contains instructions for setting up the course dev container and configuring Git inside of it. You will set this up <strong>once</strong> and reuse it for every project in this course.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Failure to follow the instructions on this page <strong>exactly</strong> as presented may result in permanently losing your work for this course! You have been warned!</p></div><p>You will create <strong>a single</strong> dev container, which you will reuse for all projects in this course. The structure of your dev container at the <strong>end of this course</strong> will look like:</p><ul><li><code>/workspace/</code>: This is the directory of the dev container which is shared with your host machine. <strong>Any data outside of this directory will not be saved when the container is stopped.</strong><ul><li><code>.devcontainer/</code>: This directory contains the configuration for the dev container itself. Do not modify this directory.</li><li><code>scripts/</code>: This directory contains miscellaneous scripts for the course. A course staff member will provide instructions on how to use these utilities, if necessary.</li><li><code>README.md</code>: This is the file you are currently reading. This file contains helpful reminders and instructions for using the dev container.</li><li><code>SEMESTER-project-1-USERNAME/</code>: This is your personal project 1 repository, where <code>SEMESTER</code> is the current semester (e.g.: <code>sp25</code>) and <code>USERNAME</code> is your GitHub username (e.g.: <code>ghost</code>). It will be created for you when you accept the GitHub Classroom assignment for project 1 (in Canvas).</li><li><code>SEMESTER-project-2-USERNAME/</code>: Same as above, but for project 2.</li><li><code>SEMESTER-project-3-USERNAME/</code>: Same as above, but for project 3.</li><li><code>SEMESTER-project-4-USERNAME/</code>: Same as above, but for project 4.</li><li><code>SEMESTER-project-5-USERNAME/</code>: Same as above, but for project 5.</li></ul></li></ul><p>To set up the course dev container, first download <a href="https://github.com/csci-442-mines/student-env/releases/latest/download/student-env.zip" target="_blank" rel="noreferrer">this</a> file and extract it to a directory of your choice (Somewhere that is easy to access and safe from accidental deletion). Then, open the top level of extracted directory in VS Code by any <strong>one</strong> of the following methods:</p><p><em>Note: when we refer to the <strong><u>system</u> terminal</strong> below, we mean your operating system&#39;s terminal, as described on the <a href="/install-docker">Install Docker</a> page.</em></p><ol><li>(Recommended) Open VS Code and select <code>File &gt; Open Folder...</code>: <img src="'+t+'" alt="Open folder dropdown" data-zoomable="true"> Then, navigate to the directory where you extracted the course dev container. You should see VS Code switch to the directory you selected.</li><li>Right-click on the directory and select <code>Open with Code</code>. You should see VS Code open with the directory loaded in the window. Note that this option may not be available on all systems.</li><li>Run <code>code PATH_TO_DIRECTORY</code> in your system&#39;s terminal (Where <code>PATH_TO_DIRECTORY</code> is the actual path to the directory). You should see VS Code open with the directory loaded in the window.</li></ol><p>Now that you have the directory open in VS Code, you should see a popup notification, typically on the bottom right of the window, that says <code>Reopen in Container</code>:</p><p><img src="'+i+'" alt="Reopen in Container popup" data-zoomable="true"></p><p>Click on <code>Reopen in Container</code> to build the dev container (which can take a few minutes). Once the container is built, the loading bars will disappear. Open the <strong><u>integrated</u></strong> terminal (Not the <u>system</u> terminal) by selecting <code>Terminal &gt; New Terminal</code> from the top menu:</p><p><img src="'+o+'" alt="New terminal dropdown" data-zoomable="true"></p><p>You should see a terminal window open at the bottom of the window:</p><p><img src="'+s+`" alt="Integrated terminal" data-zoomable="true"></p><p>In the integrated terminal, run the following command to verify that the dev container is correctly set up to save your work:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /workspace/hello-world.txt</span></span></code></pre></div><p>If you navigate to the directory where you extracted the course dev container in your system&#39;s file explorer/viewer, you should see a new file named <code>hello-world.txt</code>. If you do not see this file, please double-check you&#39;ve followed the instructions above and try again. If you still have issues, please stop immediately and reach out to the course staff for help.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not proceed past this point until you have verified that the dev container is correctly set up to save your work!</p></div><h2 id="setup-git-inside-the-dev-container" tabindex="-1">Setup Git Inside the Dev Container <a class="header-anchor" href="#setup-git-inside-the-dev-container" aria-label="Permalink to &quot;Setup Git Inside the Dev Container&quot;">​</a></h2><p>First, configure Git with your name and email address by running the following commands in the integrated terminal:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;YOUR_NAME&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;YOUR_EMAIL&quot;</span></span></code></pre></div><p>Where <code>YOUR_NAME</code> is your GitHub username (e.g.: <code>ghost</code>) and <code>YOUR_EMAIL</code> is the email address (e.g.: <code>ghost@example.com</code>).</p><p>Now, let&#39;s set up authentication with GitHub. You can use any <strong>one</strong> of the following methods:</p><ol><li><p>(Recommended) Clone a private repository from GitHub for the first time <strong>using HTTPS</strong>. When you clone a private repository <strong>using HTTPS</strong> for the first time, you will be prompted to authenticate with GitHub:</p><p><img src="`+a+`" alt="Clone first time" data-zoomable="true"></p><p>Click <code>Allow</code>, and follow the prompts to sign in with your GitHub account. Note that if you do not use the HTTPS URL, you will get an error message when cloning the repository.</p></li><li><p>Manually setup SSH keys. You can follow the detailed instructions <a href="https://docs.github.com/en/authentication/connecting-to-github-with-ssh/adding-a-new-ssh-key-to-your-github-account" target="_blank" rel="noreferrer">here</a>, but in short, generate new SSH keypair by running the below commands in the integrated terminal:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519</span></span></code></pre></div><p>Then, get the public key with:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519.pub</span></span></code></pre></div><p>Finally, go to your <a href="https://github.com/settings/keys" target="_blank" rel="noreferrer">GitHub SSH keys settings</a>, click <code>New SSH key</code> (<strong>Not</strong> <code>New GPG key</code>), give a descriptive title, set the key type to <code>Authentication key</code>, copy-paste the public key into the key field, and click <code>Add SSH key</code>.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Once you&#39;ve completed the setup instructions above, head over to the <a href="/per-project-setup">Per-Project Setup</a> page for instructions on creating and cloning a repository for each project in this course.</p></div><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="vs-code-takes-a-very-long-time-to-build-the-dev-container-fails-to-build-the-dev-container" tabindex="-1">VS Code Takes a Very Long Time to Build the Dev Container/Fails to Build the Dev Container <a class="header-anchor" href="#vs-code-takes-a-very-long-time-to-build-the-dev-container-fails-to-build-the-dev-container" aria-label="Permalink to &quot;VS Code Takes a Very Long Time to Build the Dev Container/Fails to Build the Dev Container&quot;">​</a></h3><ul><li><p>Symptom: building the dev container takes a very long time (e.g.: 20+ minutes) or VS Code fails to build the dev container with an error message related to Docker.</p></li><li><p>Solution: this can happen if you have a slow/dysfunctional internet connection or computer. To workaround this, we provide a pre-built dev container image (<code>ghcr.io/csci-442-mines/student-env</code>). To use it, edit the <code>.devcontainer/devcontainer.json</code> like so:</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">// Use the prebuilt image (Mutually exclusive with &quot;build&quot;!):</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- // &quot;image&quot;: &quot;ghcr.io/csci-442-mines/student-env:latest&quot;,</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ &quot;image&quot;: &quot;ghcr.io/csci-442-mines/student-env:latest&quot;,</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">// Build the image yourself (Mutually exclusive with &quot;image&quot;!):</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- &quot;build&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-   &quot;dockerfile&quot;: &quot;Dockerfile&quot;,</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-   &quot;context&quot;: &quot;..&quot;</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">- },</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ // &quot;build&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ //   &quot;dockerfile&quot;: &quot;Dockerfile&quot;,</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ //   &quot;context&quot;: &quot;..&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+ // },</span></span></code></pre></div><p><em>Note: the <code>+</code> and <code>-</code> symbols are non-literal and are used to indicate lines that should be added and removed, respectively. If you don&#39;t already have an <code>image</code> line, you can just add the <code>image</code> line like above and comment out the <code>build</code> section.</em></p><p>Then, rebuild the dev container by clicking on the green <code>Reopen in Container</code> button in the bottom right corner of the window or by opening the command palette (<code>CTRL+SHIFT+P</code> or <code>CMD+SHIFT+P</code> on Mac) and typing <code>Dev Containers: Rebuild Container</code>.</p></li></ul><p><em>This page created with the help of Claude AI.</em></p>`,29)]))}const f=n(c,[["render",h]]);export{b as __pageData,f as default};
